static int evaluateRPN(String expression) {
    Stack<Integer> stack = new Stack<>();
    for (String token : expression.split(" ")) {
        switch (token) {
            case "+", "-", "*", "/" -> {
                int b = stack.pop();
                int a = stack.pop();
                int result = switch (token) {
                    case "+" -> a + b;
                    case "-" -> a - b;
                    case "*" -> a * b;
                    default -> a / b;
                };
                stack.push(result);
            }
            default -> stack.push(Integer.parseInt(token));
        }
    }
    return stack.pop();
}

public static void main(String[] args) {
    System.out.println(evaluateRPN("5 3 + 8 2 - *"));
}

static boolean isBalanced(String s) {
    Stack<Character> stack = new Stack<>();
    Map<Character, Character> pairs = Map.of(')', '(', ']', '[', '}', '{');
    for (char c : s.toCharArray()) {
        if (c == '(' || c == '[' || c == '{') {
            stack.push(c);
        } else if (pairs.containsKey(c)) {
            if (stack.isEmpty() || stack.pop() != pairs.get(c)) return false;
        }
    }
    return stack.isEmpty();
}

public static void main(String[] args) {
    System.out.println(isBalanced("({[]})"));
    System.out.println(isBalanced("([)]"));
    System.out.println(isBalanced("(()"));
}

class VisitCounter {
    private final Hashtable<String, Integer> counts = new Hashtable<>();

    synchronized void visit(String url) {
        counts.merge(url, 1, Integer::sum);
    }

    int getCount(String url) {
        return counts.getOrDefault(url, 0);
    }
}

