static void corruptViaVectorApi(Vector<Integer> v) {
    v.insertElementAt(999, 0); // Stack nie ma prawa 'wiedziec', ze to sie stanie
}

public static void main(String[] args) {
    Stack<Integer> stack = new Stack<>();
    stack.push(1); stack.push(2); stack.push(3);
    System.out.println("Przed: " + stack + ", peek=" + stack.peek());

    corruptViaVectorApi(stack); // metoda przyjmuje Vector<Integer> - Stack pasuje!
    System.out.println("Po: " + stack + ", peek=" + stack.peek()); // peek WCIAZ pokazuje 3, ale struktura jest 'zepsuta'

    // Naprawa: Deque nie ma tego problemu, bo NIE implementuje List
    Deque<Integer> safeStack = new ArrayDeque<>();
    safeStack.push(1); safeStack.push(2); safeStack.push(3);
    // Deque NIE MA insertElementAt ani get(index) - niemozliwe zepsucie LIFO w ten sposob
    System.out.println("Deque (bezpieczny): " + safeStack);
}

