long stackTime = measure(() -> { Stack<Integer> s = new Stack<>(); for (int i = 0; i < n; i++) s.push(i); for (int i = 0; i < n; i++) s.pop(); });
long dequeTime = measure(() -> { Deque<Integer> d = new ArrayDeque<>(); for (int i = 0; i < n; i++) d.push(i); for (int i = 0; i < n; i++) d.pop(); });
System.out.println("Stack: " + stackTime + "ms, ArrayDeque: " + dequeTime + "ms");

static long measure(Runnable task) {
    long start = System.nanoTime();
    task.run();
    return (System.nanoTime() - start) / 1_000_000;
}
